N = {}

N['xu'] = ('趙蕤自序，開元四年（七一六）作於梓州郪縣長平山。全書的門戶在這裡：造車的盼人富貴，造箭的盼人受傷，不是心腸有別，是各自的手藝逼出來的——一上來就把「立場由位置決定」擺在檯面上。接著說孔子作《春秋》《孝經》是「防萌杜漸」，可是「作法於理，其弊必亂」，法一旦立下，弊病也跟著長出來，所以三代不同禮、五霸不同法，不是互相翻案，是各救各的弊。末尾自報家門：王者之政化之，霸者之政威之，強國之政脅之；在霸者之朝行王者之化就「悖」，在強國之世行霸者之威就「乖」。「霸者，駁道也」——白黑雜合，不純用德，只問成不成，不問怎麼成。他知道這話犯忌，所以說「恐儒者溺於所聞，不知王霸殊略」，這才是書名「長短」的來歷。自序稱「總六十有三篇，合為十卷」，今本實存九卷六十四篇，第十卷《陰謀》已佚——篇數與序不合，《四庫提要》疑是序文傳寫之訛。')

N['j1'] = ('八篇，講「人」。次第是拆開的：先立君道（用非其有）、再立用人之法（各因其長）、再給人分品（五儀、英俊豪傑）、再按品授位（三公九卿之事各有所在）、再說怎麼看得準（八徵、六驗）、再附一篇看相、再說士為什麼要禮遇、最後收在一篇政體上。整卷只做一件事：把「識人」從德性話題改造成技術話題。')
N['j2'] = ('四篇，講「君臣」與「國」。上一卷的眼睛對著臣下，這一卷的眼睛對著上頭與整體：君德有王霸強弱之分，臣行有六正六邪，性情各有所長亦各有所偏（《人物志》十二材的失處），國家則有六主、九風、四亂、四危可驗。底本原缺總題，《四庫提要》按體例推定當作「文中」——本頁所據的讀畫齋叢書本卷端正題「長短經卷第二　文中」，提要所見的那個本子確是脫了兩個字。')
N['j3'] = ('四篇，是全書的樞紐，書名「反經」即出於此卷第十三篇。上兩卷立了一整套法，這一卷把它全部翻過來看：仁義禮樂名法刑賞八者，每一樣都同時生出它的反面；《是非》一篇乾脆把古訓兩兩對舉，一「是曰」一「非曰」，五十三對，不作裁決；《適變》說法與時詭則法立而時益亂；《正論》把九流諸家各自的長與弊逐家點出。讀《反經》只讀這一卷，未必讀錯。')
N['j4'] = ('一篇，《霸圖》。從周室東遷一路寫到隋亡唐興，是全書最長的一卷。正文只五千餘字，趙蕤自注三萬餘字，把《史》《漢》《三國》《晉書》以下的開國與亡國一段段嵌進去——正文是骨，注是肉，得連著讀。')
N['j5'] = ('一篇，《七雄略》。專講戰國：分封之利與尾大之弊，蘇秦合縱、張儀連橫的說辭幾乎全文錄入注中，末尾一篇「論曰」比較五等與郡縣的長短，落在「郡縣而理則生布衣之心，五等禦代則有縱橫之禍」——兩頭都有弊，所以只能「兢兢業業，日慎一日」。')
N['j6'] = ('一篇，《三國權》。開頭一句「地利不同，勢使之然耳」定調：吳蜀以四州之地與曹氏爭衡，靠的不是人和而是地形。於是全卷按地理鋪開——蜀之天府、荊之要衝、吳之江湖，一處一處算它的攻守之便。底本無總題，《四庫提要》按體例推定當作「霸紀下」。')
N['j7'] = ('二篇。《懼戒》是全書篇幅第二的長篇，把改朝換代的事例排成一條線，結論只一句：「天下者，非一人之天下也，天下之天下也。」《時宜》則舉同一個主意在不同時候的不同下場——陳涉不當立六國後，酈食其勸漢王立六國後，張良發八難駁倒他：同一策而一可一不可，差別只在時。')
N['j8'] = ('十九篇，全書最散也最好讀的一卷，每篇短則二三百字，各拈一個世情的反常處：釣情、詭信、忠疑、用無用、恩生怨、詭順、難必、運命、大私、敗功、昏智、卑政、善亡、詭俗、息辯、量過、勢運、傲禮、定名。合起來是一部「常識的反面教材」——恩是怨的來處，無用是大用，大私才成其為公，傲慢也可以是一種禮。')
N['j9'] = ('二十四篇，兵權。卷首有一段小序（本頁附在《出軍》篇首）說「自古兵書殆將千計，若不知合變，雖多亦奚以為」，所以這一卷是刪削過的兵書提要：出軍、練士、結營、道德、禁令、教戰、天時、地形、水火、五間、將體、料敵、勢略、攻心、伐交、格形、蛇勢、先勝、圍師、變通、利害、奇兵、掩發、還師。骨架取自《孫子》《六韜》《尉繚》，每條後面配一樁史事。四庫本此卷的篇次自「第一」起另編，與全書六十四篇的通行編次不合，本頁從通行編次。')

P = {
 1: '全書第一篇，立君道。老子「以正理國，以奇用兵」，荀卿「人主以官人為能，匹夫以自能為能」，堯有九子分職而己不能為一，漢高自陳不如張良蕭何韓信而能用之——四條證據指向同一句話：「知人者，王道也；知事者，臣道也。」「用非其有，如己有之」是這一篇的句眼；人主自己動手，就是不能任賢，賢者惡之，功名與國家一起壞掉。末尾五個「君之體也」把君道收成五條可記的話。',
 2: '承上篇，講用人之短長。伊尹築土工，強脊者負土、眇者推車、傴者塗牆；管仲自陳五個人各當一職，而「欲霸王，則夷吾在此」；黃石公說「使智、使勇、使貪、使愚」，因其至情而用之。魏武的令說得最狠：進取之士未必有德行，陳平不篤行、蘇秦不守信，可是漢業與弱燕都靠他們——「任其長也」。全篇拒絕用一把尺子量人。',
 3: '把人分等。孔子的「五儀」：庸人、士人、君子、賢人、聖人，各有可驗的樣子；《鈐經》另出一套「英、俊、豪、傑」，按德、信、識、才的分量遞降。這不是褒貶排序，是給上一篇的「因能授職」備一張刻度表——先有刻度，下一篇才談得上按刻度派官。',
 4: '刻度落到官階上。伊尹說智通大道、應變不窮者為三公，通地理、能利不利者為九卿，通人事、實府庫者為大夫，忠正強諫、去私立公者為列士——「道德仁義定而天下正」。後半是太公的一段將才分級：從只配去街巷察奸的多言者，一路數到十人之將、百人之將、千人、萬人、十萬、百萬之將，每一級配一副神態。器與位不相稱，如以升盛斛，滿則棄。',
 5: '難處在這裡：人不易知，知人不易。光武看錯龐萌，曹操看錯張邈；狙者類智、愚者類君子、戇者類勇，白骨疑象、碔砆類玉。所以要有術——問之以辭觀其變、間謀觀其誠、遠使以財觀其廉、試之以色觀其貞、告之以難觀其勇、醉之以酒觀其態；《莊子》另有九徵，李克有五視，姜太公有八徵。整篇是一套可操作的觀察程序，不是相人之學。',
 6: '接上篇的「不易知」，另出一路：看相。先立其來歷——《左傳》叔服相公孫敖二子、《漢書》高祖相劉濞有反相；再立其限度——「富貴在於骨法，憂喜在於容色，成敗在於決斷」。中段是全書最專門的一段文字：面有五嶽四瀆、五官六府，九品之侯自顴骨數到骨角，再逐一說眼、鼻、口、齒、鬢、指。其中不少字底本以方括號描述字形，Unicode 無字，本頁仍其舊（見卷末凡例）。',
 7: '講士為什麼要禮遇。齊桓公五往而見小臣稷，一句「縱夫子傲爵祿，吾庸敢傲霸王乎」；顏斶當面說「生王之頭，曾不如死士之壟」；淳于髡問齊宣王好馬好味好色都肯將就，為什麼獨獨要等堯舜之士才肯好士。末段轉到士自己這一面：士亦有屈伸窮達，不遇則已。全篇的語氣比前六篇熱。',
 8: '卷一的收束，從人轉到政。管子十五條「措國於不傾之地」被拆開逐條作注：有德、務五穀、養桑麻、順人心、使人各為所長、嚴刑罰、信慶賞、量人力、不強人所惡、不偷一世之宜。末尾一串十五事——明版籍、審什伍、限夫田、定刑名……「雖聖人復起，必此言也」。結句點題：「夫欲論長短之變，故立政道以為經焉」，先立經，下面才好說權。',
 9: '卷二之首，論君德。開篇把治術分四層：三皇無言而化流四海，帝者有言有令而天下太平，王者制人以道，霸主制士以權、結士以信、使士以賞。再把它折成一句可用的話：「任德多、用刑少者，五帝；刑德相半者，三王；仗刑多、任德少者，五霸；純用刑，強而亡者，秦。」以下全是史例對勘——高祖與光武孰優，文景與成康可比否，漢武與秦皇同為立功之君而非守成之主——虞世南《帝王略論》與班固諸贊是注中最主要的兩個來源。',
 10: '君德之後說臣行。核心是「六正六邪」：聖臣、大臣、忠臣、智臣、貞臣、直臣為六正；具臣、諛臣、奸臣、讒臣、賊臣、亡國之臣為六邪。跟著是一長串難題：楊阜敢言而袁子不許為忠，陳群終日不言人主之非而反為忠；季布為人奴而不死，管仲不死公子糾——「不恥不死公子糾，而恥威之不申於諸侯」。臣行不是一條直線，判準在所處的位置與所任的事。',
 11: '短篇而要緊：把「德」改寫成可校正的偏差表。孔子「性相近，習相遠」起頭，接《人物志》十二種材：厲直剛毅失在激訐，柔順安恕失在少決，雄悍傑健失在多忌，精良畏慎失在多疑……每一種長處都自帶一個失處。再引《文子》「心欲小，志欲大，智欲圓，行欲方，能欲多，事欲少」。治性之道是「審己之所有餘，而強其所不足」——不求全德，求補偏。',
 12: '把國家當成可診斷的對象。三張表：六主（王、治、存、衰、危、亡），九風（禮國、衰國、乖國、亂國、荒國、叛國、危國、亡國……），再加四亂四危。荀悅的原話與《尹文子》《叔向》的話作注，逐條配一個症候。讀法是倒過來的——不是先問這個君好不好，是先看風氣像哪一條。',
 13: '書名所自。一句話立住：三代之亡不是法亡，是「御法者非其人」。接著把仁、義、禮、樂、名、法、刑、賞八樣逐一翻面——仁所以博施，亦所以生偏私；賞所以勸忠能，亦所以生鄙爭。再引《韓詩外傳》「士有五反」、太公「明罰則人畏懾，人畏懾則變故出」、慎子「忠未足以救亂代，而適足以重非」。不是反對法度，是提醒每一件好東西都自帶它的敗壞方式。',
 14: '全書體例最特別的一篇。凡五十三對，一「是曰」一「非曰」，每一對都引古訓：既明且哲以保其身／士見危致命；惡訐以為直／惡隱惡以為仁；疑今者察之古／一噎而禁人食。趙蕤自己幾乎不下判斷，自注只有三百餘字。開頭一句「前誌垂教，今皆可以理違」就是全篇的態度——古訓兩兩相消，剩下的只有當下的權衡。',
 15: '講「時」。先王當時而立法，時移而法不變，則「法與時詭」，法愈立而時愈亂。中段用王道與霸術對舉，再引《道德經》「我無為而人自化」與《文子》對「無為」的界定——不是引之不來推之不往，是循理舉事、因資立功。後半逐家品評：黃老之風蓋帝道（曹參治齊、代蕭何為相的舊事），孔氏之術蓋王道（七教三至），墨翟之術蓋強本，商鞅申韓之術貴尚譎詐而尊君強兵有可取。結語不偏袒任何一家：「雖經緯殊制，救弊不同，然康濟群生，皆有以矣。」——本篇後半三千餘字底本脫去，本頁據四庫全書本補足，見卷末凡例。',
 16: '對九流下總判。先立標準：六藝各有所長亦各有所失——《詩》之失愚，《書》之失誣，《樂》之失奢，《易》之失賊，《禮》之失煩，《春秋》之失亂。然後逐家：儒家出於司徒之官，長在祖述堯舜，弊在僻儒嘩眾取寵；道家出於史官，長在秉要執本，弊在絕禮樂棄仁義；以下陰陽、法、名、墨、縱橫、雜、農各出一長一弊。體例仿《漢書·藝文志》而每家都補上「及其弊也」一段。',
 17: '卷四，也是全書最長的一篇。從周室三百年之盛講到隋亡唐興，正文是一條極簡的編年綱目，趙蕤自注三萬餘字把血肉填進去：陳涉吳廣之起、蒯通說范陽令、蕭何勸漢王王漢中、韓信井陘背水、婁敬勸都關中、光武昆陽、官渡、赤壁、劉淵石勒、宋齊梁陳的禪代、李密與王世充……讀這一篇要連注一起讀，正文離開注幾乎不成文章。底本把本篇與下一篇《七雄略》併成一頁且前後錯簡，本頁據四庫全書本重新分篇，見卷末凡例。',
 18: '卷五，專論戰國。開頭一段講分封：「器大不可以獨理，蓄重不可以自守」，所以劃野分疆；但「厚下之典，弊於尾大」。接著蘇秦說燕、趙、韓、魏、齊、楚的六段合縱辭，張儀破縱連橫的六段對辭，樂毅、魯仲連、范雎、黃歇、甘羅的說辭幾乎全文收在注裡——是一部縮寫的《戰國策》。末尾「論曰」比較五等與郡縣：兩制都有弊，所以治亂終究在人不在制。',
 19: '卷六，論三國。定調的是一句地理話：袁紹劉表馬超呂布皆一時之傑而六七年間夷滅十八九，吳蜀以四州之地反能與曹氏爭衡，「則地利不同，勢使之然耳」。於是全篇按地走——蜀之沃野與天獄、荊之要衝、吳之江湖，一處一處算攻守之便，再以荀悅、習鑿齒、陸機諸論作結。末段引賈誼《治安策》談封建與郡縣，收到「有國者不可不察」。',
 20: '卷七之首，全書第二長篇。題作「懼戒」，講的是改朝換代：文王問太公伐商之時，叔向論子干不能濟的五難，子貢一出而亂齊、存魯、破吳、霸越，秦之亡、王莽之篡、更始之敗、隋之滅……一路排下來，落在兩句話上：「天下者，非一人之天下也，天下之天下也」，和「安不忘危，存不忘亡」。篇名不是說怕，是說怕了才知道戒。',
 21: '同一件事，在不同的時候是兩件事。陳涉至陳，張耳陳餘勸他不要稱王而先立六國後；楚漢相持，酈食其勸漢王立六國後，張良發「八難」逐條駁倒——同一條計策，一時可行一時必敗，差別只在形勢。後半又舉沮授勸袁紹迎獻帝（紹不從而敗）與張弘策勸蕭衍迎南康王（衍不從而成），連「挾天子以令諸侯」這樣的定論也要看時候。結句：「隨時變通，不可執一矣。」',
 22: '卷八之首，講怎麼說話。先引孔子「未見顏色而言謂之瞽」、「未信則以為謗己」，再整段搬《韓非子·說難》：說之以厚利則見卑賤，說之以名高則見無心；與之論大人則以為間己，與之論細人則以為鬻權。後半自出一套「釣」法——以言釣、以事釣、以賢釣、以色釣，喜怒欲懼憂各有顏色可驗。結語：「夫人情必見於物，能知此者，可以納說於人主矣。」',
 23: '信不是無條件的。「君子貞而不諒」、「信近於義，言可覆也」——所以「唯義所在，不必信也」。解揚受楚賂而反其言，說的是「義無二信，信無二命」；直躬證父攘羊，孔子以為父子相隱才是直。後半更進一層，收在一句翻案話上：「譎即信也，詭即忠也。夫詭譎之行，乃忠信之本焉。」',
 24: '忠而見疑。毀譽是非本無定準：同一個陳平，毀之則疏、譽之則親；同一個魏尚，繩之以法為罪、施之以德為功。《呂氏春秋》亡斧疑鄰、公息忌以組為甲兩段說的是「有所尤」——心裡先有了偏，看什麼都像。末段用《淮南子》窺面於盤水則圓、於杯則隋作結：面形沒變，變的是拿什麼照。「今吾雖欲正身而待物，庸詎知世之所自窺於我者乎？」',
 25: '短篇。羅網得鳥的只一目，可是只張一目的網永遠得不到鳥；鳥飛得遠靠六翮，可是沒有眾毛就飛不遠。莊子與惠子論「無用之用」：人走路只用得著腳掌那麼大的地，把周圍削到黃泉，腳下那塊還有用嗎。後半落到實處——樊英、楊厚應徵而無異能，李固、朱穆譏其盜名，可是後進因之成器、世主因之得眾。「原其無用，亦所以為用也。」',
 26: '怨從恩來。諺曰「非所怨，勿怨」，怨從來不生在疏遠的人身上：越人開弓射我，我談笑處之；兄弟開弓射我，我就哭了——「無他，戚之也」。《小弁》之怨正是親親，親親即仁。杜鄴的話說得最切：「戚而不見異，親而不見殊，孰能無怨？」結語一句：「怨也者，親之也；恩也者，怨之所生也。」',
 27: '為舊主盡力的人，新主該怎麼待。寺人披斬晉文公之袪而文公見之，得免呂郤之難；漢高賞季布之罪；魏武赦陳琳。反過來，惠公殺里克、漢祖戮丁公、石勒誅棗嵩、劉備薄許靖——同樣是「詭順」，賞與誅各有其理。范曄一句作結：「夫人守義於故主，斯可以事新主；恥以其眾受寵，斯可以受大寵。」',
 28: '「必」字最靠不住。人主欲臣之忠而忠未必信，伍員沉江、萇弘死蜀；人親欲子之孝而孝未必愛，孝己憂而曾參悲。狐卷子答魏文侯：父賢不過堯而丹朱放，子賢不過舜而瞽叟拘，弟賢不過周公而管蔡誅——「望人者不至，恃人者不久」。結語數了一遍不可必的東西：權利合者權利盡而交疏，以色事人者色衰而愛絕，慈父不愛無益之子。',
 29: '講命。荀悅的「三勢」是這一篇的骨架：死生有命是正理，不得其死是未可死而死，幸而免是可以死而不死。順著推到教化上——有不教而自成的，有待教而後成的，有雖教而不成的。既不肯把一切歸給天，也不肯把一切歸給人：「天地之道，有同有異」，據異責同則惑，守同求異則弊。末句仍落在人事上：「君子盡心焉、盡力焉，以邀命也。」',
 30: '最短的幾篇之一，卻是全書最漂亮的一個翻轉。「知與之為取，政之寶也」、「將欲取之，必故與之」。黃石公：「得而勿有，立而勿取；為者則己，有者則士。」湯說萬方有罪朕身受之，文王說苟有仁人何必周親——「先王非無私也，所私者與人不同，此知大私者也」。結句：「夫唯不私，故能成其私；不利而利之，乃利之大者矣。」',
 31: '敗可以變成功。楚恭王臨終自請惡諡，子囊卻說「有是寵也而知其過，可不謂之恭乎」，於是諡恭——這是「因過以為功」。司馬師把王昶、陳泰之敗攬為己過，習鑿齒論曰「過銷而業昌」。反過來，諱敗推過、歸咎萬物，則上下離心。「因禍為福，轉敗為功，自古然矣。」',
 32: '智為什麼會昏。不是愚，是被聲色、勢利、怒愛奪去了。齊人遺魯女樂而孔子去魯，昏於聲色；平原君貪馮亭上黨而趙陷長平，昏於利；還有昏於怒、昏於愛的。所以論貴賤、辯是非「必且自公心言之，自公心聽之」。范曄的話作結：利不在自己身上，謀事時心思才不向著自己。',
 33: '政貴卑近。「濟溺人以金玉，不如尋常之纏」；餓了一百天的人不肯等粱肉。韓非說得直白：微妙之言是上智都難的，拿來當眾人之法，就沒有人能懂。所以君子「所言者不出於名法權術，所為者不出於農稼軍陣」。叔孫通說禮是「因時世人情而為之節文」，文帝對張釋之說「卑之，無甚高論，令今可施行」——這一篇是全書對「高論」最不客氣的一篇。',
 34: '善要積起來才算數。「積善之家必有餘慶」，可是拿一杯水去救一車薪之火，火不熄就說水不勝火，這是「與不仁之甚者」；五穀不熟，不如稊稗。尸子說吃一頓飯就問人「我胖了沒有」，人人笑他，可治天下的人正這樣。所以見徐偃亡國就說仁義不足杖、見承桑失統就說文德不足恃，都是一飯問肥。',
 35: '世俗的好惡與事情的實情常常相反。楚靈王死於乾溪，芊尹申亥順其欲而殉以二女——順之而失義；子反受穀陽之酒而斃——愛之而為害；臧武仲說孟孫之惡我是藥石、季孫之愛我是美疢——惡之而為美。後半整段引韓非：不棄、仁人、君子、有行、有俠、高愨、剛材、得人，這八個好名聲，一一對著一項公家的損失。',
 36: '辯不必辯，看本與跡就夠了。水之寒、火之熱、金石之堅，未嘗有言而人莫不知，因為「信著乎其體」。行有本：立身以義而孝為本，喪紀有禮而哀為本，戰陣有列而勇為本。事有跡：齊威王封即墨大夫、烹阿大夫，一個毀日至而田野辟，一個譽日聞而田野荒。「若操其本行，以事跡繩之，則善惡無所逃矣。」',
 37: '同一件事，看的人站在哪一黨，說法就不同。管仲九合諸侯一匡天下，孔子卻說「管仲之器小哉」——嫌他不勉齊桓至於王；虞卿說楚且攻燕而稱楚「天下無敵」，其實是說楚力不能及燕。「非詭議也，各從其黨言之耳。」孔子那句「觀過，斯知仁矣」，在這裡被讀成一種判斷技術。',
 38: '君子小人未必是性，多半是勢。《文子》：有餘則讓，不足則爭；讓則禮義生，爭則暴亂起。淮南子：會游泳的人救不了溺水的，手腳自顧不暇；林中不賣柴，湖上不賣魚。所以「世治則小人守正而利不能誘，世亂則君子為奸而刑不能禁」。莊子那句話是這一篇的骨頭：堯舜之世無窮人不是智得，桀紂之世無通人不是智失，「時勢適然」。',
 39: '傲也可以是禮。侯嬴故意讓魏公子在市中久立以觀之，公子愈恭，市人以嬴為小人而以公子為長者——「嬴欲就公子之名」。王生使張廷尉當眾為他結襪，也是同一手。全篇說的是一種代價很高的成全：用自己的名聲去換對方的名聲。',
 40: '卷八的收束，也是全書最像字典的一篇。道、德、仁、義、禮、智、信，一個一個給界說：道者人之所蹈，德者人之所得，仁者愛也，義者宜也，禮者履也……接著把名與實的關係說透：不是物有自然之名、理有必定之稱，是「欲辯其實則殊其名，欲宣其志則立其稱」。名分一定，爭端就少了一半——這一篇是卷九談兵的前提。',
 41: '卷九之首。篇前有一段小序（底本繫於本篇之首，四庫本置於卷端且作「孫子曰」）：文事必有武備，自黃帝與蚩尤以下無代無兵，「自古兵書殆將千計，若不知合變，雖多亦奚以為」。正文講出師：兵者凶器，戰者危事，不得已而用之；再分義兵、應兵、忿兵、貪兵、驕兵五種，王、勝、敗、破、滅五個下場。末段是授鉞之禮——「閫以內者，寡人制之；閫以外者，將軍制之」。',
 42: '選人編伍。腹心一人、謀士五人、天文三人、地形三人、兵法九人……一直排到方士二人，是一份參謀部編制表。再按性情分卒：敢死樂傷者聚為一卒，勃氣壯勇者聚為一卒，能逾高超遠輕足善走者聚為一卒，故王臣失勢欲復見功者聚為一卒。用人之長的道理，到這一卷變成了編制。',
 43: '結營。短篇，通篇是式法——將軍居青龍，軍鼓居逢星，士卒居明堂，伏兵於太陰，軍門居天門……不飲死水，不居死地、地柱、地獄，無休天灶，無當龍首。這一套與下面《天時》一篇同屬唐代兵書中的數術部分，本頁一仍其舊，不作刪節。',
 44: '兵不可出者三：不和於國、不和於軍、不和於陣。接著是孫子的「道」——令人與上同意，可與之死，可與之生。黃石公說將不言渴、不言倦、冬不服裘、夏不操扇，是「禮將」。越王含蓼問疾，吳起吮疽恤士，陽門慟哭，單醪投河——四個舊典都在講同一件事：士卒為什麼肯死。',
 45: '禁令。孫子「視卒如嬰兒，故可與之赴深溪」與「厚而不能使，愛而不能令，譬若驕子」兩句並列，愛與法要一起立。主體是吳起的「七禁」——輕、慢、盜、欺、背、亂、誤，每一條下面列出具體情狀（期會不到、聞鼓不行、受令不傳、揚聲惑眾……），凡幾十事，是一份可執行的軍法條文。',
 46: '教戰。「不教人戰，是謂棄之」。從一人學戰起，成而合十人，十人成而合百人，漸至三軍。後半是陣法：左校青龍、右校白虎、前校朱雀、後校玄武、中校軒轅；聞鼓則進，聞金則止。收在孫子那兩句上——治眾如治寡，分數是也；鬥眾如鬥少，形名是也。',
 47: '天時。全篇是唐人軍中的占候之學：背太陰、向太陽，察五緯之光芒，觀二曜之薄蝕，以太白為主、辰星為候；細雨沐軍則有捷，回風相觸則無功；雲類群羊必走，黑氣如環山必敗。末段忽然轉了口氣：任賢使能則不占而事利，令明法審則不筮而計成，封功賞勞則不禱而福從——把前面的占候整個降了一級。底本此篇脫去四百餘字，本頁據四庫全書本補，見卷末凡例。',
 48: '地形。九地（散、輕、爭、交、衢、重、汜、圍、死）與六形，逐條給界說與處置：散地則無戰，輕地則無止，爭地則無攻，衢地則合交，重地則掠，圍地則謀，死地則戰。後半是實測的話——不知山林險阻沮澤之形者不能行軍，不用鄉導不能得地利。',
 49: '水火。火攻五事：火人、火積、火輜、火庫、火燧；發火有時，起火有日，宿在箕、壁、參、軫者風起之日。水攻則「以水佐攻者強」，舉韓信壅濰水斬龍且、關羽水淹七軍為例。末尾一句照例往回收：水火者兵之助，不是兵之本。',
 50: '用間。五間：因間、內間、反間、生間、死間，「五間俱起，莫知其道」。班超以三十六人定鄯善、破莎車的幾段全文入注。這一篇與《攻心》《伐交》合看，是全卷裡最不靠刀兵的三篇。',
 51: '將體。先破一個成見：吳起說「凡人之論將，恆觀之於勇；勇之於將，乃萬分之一耳」。將有五才——勇、智、仁、信、必；有四機——氣機、地機、事機、力機。後半列將之弊與將之八徵，末尾說「將能而君不御者勝」。',
 52: '料敵。先探敵情而後決事。派賤而勇者以輕銳試之，看它「一起一坐」是否有法度、追北是否貪利；再列三十餘條可驗的徵候——辭卑而益備者將進，辭強而進驅者將退，杖而立者饑，汲而先飲者渴，鳥集者虛，夜呼者恐，吏怒者倦。全篇幾乎是《孫子·行軍》的擴寫。',
 53: '勢。「勇怯，勢也；強弱，形也」；水之弱而能漂石，是勢。劉曄勸曹操乘取漢中之威直取蜀而操不從，遂失其機；曹操破袁紹而不急追袁尚，坐待公孫康獻首。全篇說的是同一件事的兩面——勢在時要用足，勢不在時不可強造。',
 54: '攻心。「攻心為上，攻城為下；心勝為上，兵勝為下。」何謂攻心？絕其所恃。張良勸沛公不急攻嶢關而先賂其將、再乘其懈而擊之；諸葛亮七縱孟獲。篇幅極短，卻是卷九裡被引用最多的一篇。',
 55: '伐交。「善用兵者，使交不得合。」鬥廉乘鄖人未誡而夜襲蒲騷，四邑遂離；趙充國不聽詔先擊罕開，算定先零與罕開的私心終不能合。全篇只講一件事：在敵人結成一塊之前把它拆開。',
 56: '格形。「安能動之」、「攻其所必趨」。晉文公伐曹、衛以解宋圍，孫臏圍魏救趙——「批亢搗虛，形格勢禁，則自為解耳」。與上一篇合看：伐交是拆它的外援，格形是拆它的本陣。',
 57: '蛇勢。取《孫子》「率然」之喻：擊首則尾至，擊尾則首至，擊中則首尾俱至。趙充國緩追先零而虜自溺死，曹操不追袁尚而公孫康自斬其首——急之則相救如一體，緩之則彼此離散。本篇無趙蕤自注，是全書唯一一篇。',
 58: '先勝。「善用兵者，先為不可勝，以待敵之可勝。」皇甫嵩不聽董卓速救陳倉，坐待王國自疲而破之，是這一篇的主證；後附周亞夫堅壁昌邑、司馬懿拒諸葛亮。要點在「不可勝在此，可勝在彼」——能守的是自己，能等的是對方出錯。',
 59: '圍師必闕。朱儁圍宛，賊乞降而不受，攻之不克；登土山而悟：外圍周固、乞降不受、欲出不得，所以死戰。於是解圍撤壘，賊出而擊之，大破。與《利害》一篇互為表裡——那一篇講怎麼把自己逼到死地，這一篇講不要把敵人逼到死地。',
 60: '變通。「善動敵者，形之，敵必從之。」孫臏減灶誘龐涓於馬陵，虞詡反其道增灶而退羌——同一個灶，一減一增，都成了。全篇說的是法無定法：連兵法裡最著名的一條也可以倒過來用。',
 61: '利害。「陷之死地而後生，投之亡地而後存」；又「雜於利而務可伸，雜於害而患可解」。韓信背水陣破趙是正面的例，先零、馬謖失街亭是反面的例。全書講權變到這一篇最為徹底：利與害不是兩件事，是同一件事的兩頭。',
 62: '奇兵。全書最短的一篇，一百六十餘字。「兵以正合，事以奇勝」；韓信陳船臨晉而以木罌渡夏陽，虜魏王豹。末引《經》曰：「奇正之變，不可勝窮，如環之無端。」',
 63: '掩發。「其勢險，其節短」。田單激怒即墨之卒、遺書詐降而後火牛夜出；呂蒙白衣渡江襲荊州。兩樁都不是戰場上的勝負，是在對方鬆懈的那一刻把積蓄好的力氣一次放出去。',
 64: '全書的收梢，講收兵。興師百萬，日費千金；運糧三百里則無三年之食，是謂虛國。所以「雖破敵於外、立功於內，然而戰勝者以喪禮處之」——將軍縞素請罪於君，君尊其官以奪其勢。末尾那幾句是《反經》最冷的句子：「高鳥死，良弓藏；敵國滅，謀臣亡。」亡者非喪其身，謂沉之於淵；沉之於淵者，謂奪其威、廢其權。一部教人取天下的書，結束在教人怎麼把兵權交回去。',
}
for k, v in P.items(): N['c%d' % k] = v
